# ---------- type list parsing ----------
def parse_type_list(txt):
    # returns dict type -> list of globs
    d = {}
    for line in txt.splitlines():
        line=line.strip()
        if not line: continue
        if ':' not in line: continue
        name, globs = line.split(':',1)
        name=name.strip()
        globs=[g.strip() for g in globs.split(',')]
        d[name]=globs
    return d

DEFAULT_TYPES = parse_type_list(TYPE_LIST_TXT if TYPE_LIST_TXT else "")

# ---------- helpers for errors ----------
def eprint(msg):
    sys.stderr.write(msg + "\n")

def fail(msg, code=2):
    eprint(msg)
    sys.exit(code)

# ---------- size parsing ----------
def parse_size(s):
    # returns int or raises
    if not s:
        raise ValueError("empty")
    s=s.strip()
    if not s:
        raise ValueError("empty")
    mult=1
    last=s[-1]
    num=s
    if last in ('K','k','M','m','G','g'):
        num=s[:-1]
        if last in ('K','k'): mult=1024
        elif last in ('M','m'): mult=1024*1024
        else: mult=1024*1024*1024
    if not num or not num.isdigit():
        raise ValueError("bad")
    return int(num)*mult

def parse_int(s):
    # strict int, must be digits? allow leading +? original says "invalid digit found in string"
    s=s.strip()
    if not s:
        raise ValueError("empty")
    # allow only digits? check original: threads, max-count etc. must be numbers, probably non-negative ints
    # We'll require all digits
    if s[0]=='+':
        s2=s[1:]
    else:
        s2=s
    if not s2.isdigit():
        raise ValueError("bad")
    return int(s2)

